307	    /// A convenience method which consumes and commits a savepoint.
308	    #[inline]
309	    pub fn commit(mut self) -> Result<()> {
310	        self.commit_()
311	    }
312	
313	    #[inline]
314	    fn commit_(&mut self) -> Result<()> {
315	        let sql = cmd("RELEASE", false, self.name.as_str())?;
316	        self.conn.execute_batch(sql.as_str())?;
317	        self.committed = true;
