320	
321	    /// A convenience method which rolls back a savepoint.
322	    ///
323	    /// ## Note
324	    ///
325	    /// Unlike `Transaction`s, savepoints remain active after they have been
326	    /// rolled back, and can be rolled back again or committed.
327	    #[inline]
328	    pub fn rollback(&mut self) -> Result<()> {
329	        let sql = cmd("ROLLBACK", true, self.name.as_str())?;
330	        self.conn.execute_batch(sql.as_str())
331	    }
332	
333	    /// Consumes the savepoint, committing or rolling back according to the
334	    /// current setting (see `drop_behavior`).
335	    ///
336	    /// Functionally equivalent to the `Drop` implementation, but allows
337	    /// callers to see any errors that occur.
338	    #[inline]
339	    pub fn finish(mut self) -> Result<()> {
340	        self.finish_()
341	    }
342	
343	    #[inline]
344	    fn finish_(&mut self) -> Result<()> {
345	        if self.committed {
346	            return Ok(());
347	        }
348	        match self.drop_behavior() {
349	            DropBehavior::Commit => self
350	                .commit_()
351	                .or_else(|_| self.rollback().and_then(|()| self.commit_())),
352	            DropBehavior::Rollback => self.rollback().and_then(|()| self.commit_()),
353	            DropBehavior::Ignore => Ok(()),
354	            DropBehavior::Panic => panic!("Savepoint dropped unexpectedly."),
355	        }
356	    }
357	}
