400	impl Connection {
401	    /// Begin a new transaction with the default behavior (DEFERRED).
402	    ///
403	    /// The transaction defaults to rolling back when it is dropped. If you
404	    /// want the transaction to commit, you must call
405	    /// [`commit`](Transaction::commit) or
406	    /// [`set_drop_behavior(DropBehavior::Commit)`](Transaction::set_drop_behavior).
407	    ///
408	    /// ## Example
409	    ///
410	    /// ```rust,no_run
411	    /// # use rusqlite::{Connection, Result};
412	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
413	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
414	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
415	    ///     let tx = conn.transaction()?;
416	    ///
417	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
418	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
419	    ///
420	    ///     tx.commit()
421	    /// }
422	    /// ```
423	    ///
424	    /// # Failure
425	    ///
426	    /// Will return `Err` if the underlying SQLite call fails.
427	    #[inline]
428	    pub fn transaction(&mut self) -> Result<Transaction<'_>> {
429	        Transaction::new(self, self.transaction_behavior)
430	    }
