435	    ///
436	    /// # Failure
437	    ///
438	    /// Will return `Err` if the underlying SQLite call fails.
439	    #[inline]
440	    pub fn transaction_with_behavior(
441	        &mut self,
442	        behavior: TransactionBehavior,
443	    ) -> Result<Transaction<'_>> {
444	        Transaction::new(self, behavior)
445	    }
