447	    /// Begin a new transaction with the default behavior (DEFERRED).
448	    ///
449	    /// Attempt to open a nested transaction will result in a SQLite error.
450	    /// `Connection::transaction` prevents this at compile time by taking `&mut
451	    /// self`, but `Connection::unchecked_transaction()` may be used to defer
452	    /// the checking until runtime.
453	    ///
454	    /// See [`Connection::transaction`] and [`Transaction::new_unchecked`]
455	    /// (which can be used if the default transaction behavior is undesirable).
456	    ///
457	    /// ## Example
458	    ///
459	    /// ```rust,no_run
460	    /// # use rusqlite::{Connection, Result};
461	    /// # use std::rc::Rc;
462	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
463	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
464	    /// fn perform_queries(conn: Rc<Connection>) -> Result<()> {
465	    ///     let tx = conn.unchecked_transaction()?;
466	    ///
467	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
468	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
469	    ///
470	    ///     tx.commit()
471	    /// }
472	    /// ```
473	    ///
474	    /// # Failure
475	    ///
476	    /// Will return `Err` if the underlying SQLite call fails. The specific
477	    /// error returned if transactions are nested is currently unspecified.
478	    pub fn unchecked_transaction(&self) -> Result<Transaction<'_>> {
479	        Transaction::new_unchecked(self, self.transaction_behavior)
480	    }
